-- ============================================================================
-- carbon: Carbon & Energy Efficiency joins the catalogue, the SECOND course of
-- the Energy Transition module.
--
-- Catalogue row (module 'energy_transition', the academy module the lead ruled
-- for the two Energy Transition courses; path_order 52, directly above its
-- wave sibling gasvalue at 51 and the live Commercial & Trading and Supply
-- Chain courses at 48, 49 and 50; prereq_slug NULL, the carried-over answer
-- "no hard prerequisite inside a module"; school left at its default, as every
-- Facilities, Economics, Assurance and Commercial & Trading course leaves it,
-- so the fees are the published school-level rows) plus the three capstones
-- and their eighteen graded fields, generated by
-- tools/course-waves/carbon/gen_course.py from fields.json, precision.json and
-- capstone.json, which carbon_capstone.mjs writes from the capstone records in
-- carbon_fields_capstone.mjs through the vendored engines. The three tier
-- structures (78 lesson keys) and the 396 questions are the three deep seeds;
-- the go-live is a fifth migration and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/carbon AND the Suite production
-- upload carrying Suite main 06aef5d63 (Suite #543 MD5-0, #545 MD4-0 and #546
-- MD45-1: the Carbon Studio and Efficiency Studio page repairs this course
-- teaches, on the engines at df31f53) is live. This file does not depend on
-- gasvalue: either may be seeded first.
--
-- THE ONE SENTENCE THE COURSE IS. A tonne of CO2e is carbon counted atom by
-- atom, weighted by a declared GWP set and carried on a record that says where
-- every factor came from, and a tonne saved is priced over the life of the
-- measure that saves it; the engines refuse or name every box nobody filled
-- instead of reading it as the best case.
--
-- THE ENGINES. engines/downstream/carbonAbatement.js and energyEfficiency.js,
-- vendored sha-identical with engines df31f53 (engines #228, MD45-1); the recon
-- findings F1 to F9 were repaired upstream in MD5-0 and MD45-1.
--
-- EVERY GRADED FIELD IS A NUMBER THE ENGINE RETURNS, at full precision, graded
-- at ONE UNIT IN THE LAST PLACE THE PROMPT ASKS FOR: tonnes, tCO2e, kW and
-- dollars to two decimals at 0.01; the excess air and the efficiency to four at
-- 0.0001; the fuel saved by tuning to the WHOLE GJ at 1. That one is the wave's
-- ruling: the saving is the ratio of two efficiencies the engine rounds to six
-- decimals, so the stored figure is a few millionths off a whole number, and a
-- learner who carries the efficiencies at the four decimals the course prints
-- lands up to about half a GJ away. The grader (academy_submit_capstone) casts
-- expected, tol and answer to numeric and accepts |answer - expected| <= tol.
-- No verdict, direction or refusal is graded, nothing HELD (FINDINGS-carbon H1
-- to H4) is graded, and no field reads a date or a clock.
--
-- THE GWP SET. Every inventory is computed on IPCC AR6 GWP100 with fossil
-- methane (CH4 29.8, N2O 273), named in the Associate and Expert prompts with
-- its report and horizon. Which report to file on is H1 and is never graded.
--
-- THE PROMPTS are capstone.json's, verbatim: every condition a field needs and
-- the precision it is graded at, and nothing that hands over an answer. No
-- graded value of any tier is a number in any prompt, within its tolerance or
-- as its own rounding, and none of the engine-derived intermediates (the
-- heater methane, the carbon kilomoles, the oxygen demand, the target
-- efficiency, the absolute trap pressure, the pinch temperature, the baseline,
-- the end-year target, the capital recovery factor) is printed in any rounding
-- of three or more significant figures. No graded value is within its
-- tolerance of any number the teaching digest prints, and no two graded values
-- are within the looser of their tolerances.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('carbon', 'Carbon & Energy Efficiency', 'energy_transition', 52, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'carbon', 'beginner', 'associate',
  'OWAZA, a flow station of an invented operator: its fired heaters, its flare, its vented methane and the power it buys, as one inventory',
  'The atoms, the flare and the inventory',
  'OWAZA FLOW STATION, Ukwa Basin Energy Ltd (an invented record; every flow, factor and efficiency is invented for the course). Compute the inventory on the IPCC AR6 GWP100, fossil methane (IPCC Sixth Assessment Report, 100-year horizon): methane 29.8, nitrous oxide 273. The fired heaters burn 356000 kmol of fuel gas a year carrying 1.07 kmol of carbon per kmol, at a destruction efficiency of 0.995. The flare receives 52800 kmol a year carrying 1.46 kmol of carbon per kmol, and the operator''s flare study states a destruction efficiency of 0.97. Carbon that escapes a burner or the flare is counted as methane. A leak survey (referenced, version 2026 Q1) measured 96.5 t of vented and fugitive methane. The station buys 18400 MWh of electricity at a SYNTHETIC factor of 0.387 tCO2 per MWh from a referenced supplier statement (Scope 2). Every other line is Scope 1. Give six numbers, each to two decimals. (1) The fired heaters'' CO2 in tonnes. (2) The flare''s CO2 in tonnes. (3) The flare''s methane in tonnes. (4) The flare''s methane line in tCO2e. (5) Scope 1 in tCO2e. (6) The inventory total, Scope 1 and Scope 2, in tCO2e.',
  jsonb_build_array(
    jsonb_build_object('key','owaza_heater_co2_t', 'label','Fired heaters'' CO2', 'unit','t CO2', 'expected',16680.088739, 'tol',0.01),
    jsonb_build_object('key','owaza_flare_co2_t', 'label','Flare CO2', 'unit','t CO2', 'expected',3290.788818, 'tol',0.01),
    jsonb_build_object('key','owaza_flare_ch4_t', 'label','Flare methane', 'unit','t CH4', 'expected',37.101684, 'tol',0.01),
    jsonb_build_object('key','owaza_flare_ch4_tco2e', 'label','Flare methane line on the stated GWP set', 'unit','tCO2e', 'expected',1105.630183, 'tol',0.01),
    jsonb_build_object('key','owaza_scope1_tco2e', 'label','Scope 1', 'unit','tCO2e', 'expected',24862.76158, 'tol',0.01),
    jsonb_build_object('key','owaza_total_tco2e', 'label','Inventory total, Scope 1 and Scope 2', 'unit','tCO2e', 'expected',31983.56158, 'tol',0.01)
  )
),
(
  'carbon', 'intermediate', 'professional',
  'IGRITA, a gas conditioning plant of an invented operator: one fired heater and its fuel gas, a failed steam trap and four process streams',
  'The heater, the trap and the pinch',
  'IGRITA GAS CONDITIONING PLANT, Aluu Gas Services Ltd (an invented record; every figure is invented for the course). The fired heater burns a fuel gas of mole fractions CH4 0.912, C2H6 0.041, C3H8 0.012, CO2 0.021, N2 0.014, with the typical heating values the Efficiency Studio carries for each component. Stack 251 C, combustion air 31 C, a radiation and convection loss of 2.1 percent from the vendor''s chart, no unburned loss, the Studio''s typical flue gas and vapour specific heats and latent heat, efficiency on LHV. The dry stack oxygen reads 6.2 percent; a combustion test has declared 2.4 percent the minimum safe oxygen, and the plan is to tune to 3.1 percent. The heater burns 365000 GJ of fuel a year on LHV. A steam trap has failed open: a 5 mm orifice, the steam upstream at 7.2 bar on the gauge with the local atmosphere at 1.013 bar, a discharge coefficient of 0.68, dry saturated steam of density 4.28 kg/m3 and isentropic exponent 1.135, in service 8200 hours a year. Four process streams, at a minimum approach of 12 C: H1 regeneration gas cooler from 187 C to 55 C at 2.72 kW/K; H2 lean amine cooler from 124 C to 46 C at 6.3 kW/K; C1 rich amine preheat from 36 C to 161 C at 4.55 kW/K; C2 fuel gas heater from 29 C to 88 C at 1.85 kW/K. Give six numbers. (1) The excess air at the current oxygen, in percent, to four decimals. (2) The heater''s efficiency on LHV at the current oxygen, in percent, to four decimals. (3) The fuel saved a year by tuning to the target oxygen, in GJ, to the nearest whole GJ. (4) The steam lost through the trap in tonnes a year, to two decimals. (5) The minimum hot utility in kW, to two decimals. (6) The minimum cold utility in kW, to two decimals.',
  jsonb_build_array(
    jsonb_build_object('key','igrita_excess_air_pct', 'label','Excess air at the current oxygen', 'unit','percent', 'expected',37.86451, 'tol',0.0001),
    jsonb_build_object('key','igrita_efficiency_lhv_pct', 'label','Heater efficiency on LHV at the current oxygen', 'unit','percent', 'expected',85.021597, 'tol',0.0001),
    jsonb_build_object('key','igrita_tuning_saving_gj', 'label','Fuel saved a year by tuning to the target oxygen', 'unit','GJ a year', 'expected',7771.999995, 'tol',1),
    jsonb_build_object('key','igrita_trap_t_per_yr', 'label','Steam lost through the failed trap', 'unit','t a year', 'expected',469.68800466, 'tol',0.01),
    jsonb_build_object('key','igrita_pinch_hot_utility_kw', 'label','Minimum hot utility', 'unit','kW', 'expected',51.59, 'tol',0.01),
    jsonb_build_object('key','igrita_pinch_cold_utility_kw', 'label','Minimum cold utility', 'unit','kW', 'expected',224.13, 'tol',0.01)
  )
),
(
  'carbon', 'advanced', 'expert',
  'IKORODU, a gas distribution and power complex of an invented operator: six measures, a target and a path, and one saving priced twice',
  'The curve, the path and the saving',
  'IKORODU GAS DISTRIBUTION AND POWER COMPLEX, Lagoon Midstream Holdings Ltd (an invented record; every cost, saving and factor is invented for the course, money in US dollars). The baseline inventory, on the IPCC AR6 GWP100, fossil methane (IPCC Sixth Assessment Report, 100-year horizon): methane 29.8, nitrous oxide 273: boilers 18650 tCO2, gas turbines 23200 tCO2, flaring 5270 tCO2 and 118.4 t of unburned methane, vented and fugitive methane 64.2 t (from a referenced leak survey), and 31200 MWh of purchased electricity at a SYNTHETIC factor of 0.43 tCO2 per MWh from a referenced supplier statement. Six measures, each annualised with a capital recovery factor at a discount rate of 0.09: Tune the boilers: capital 26000 USD, savings 118000 USD a year, running cost 0 USD a year, 690 tCO2e abated a year, a life of 4 years, acting on the boilers, starting in 2027; Waste heat recovery on the gas turbine exhausts: capital 3450000 USD, savings 520000 USD a year, running cost 38000 USD a year, 4150 tCO2e abated a year, a life of 18 years, acting on the turbines, starting in 2030; Repair the steam traps: capital 52000 USD, savings 176000 USD a year, running cost 0 USD a year, 980 tCO2e abated a year, a life of 3 years, acting on the boilers, starting in 2027; Flare gas recovery compressor: capital 6100000 USD, savings 410000 USD a year, running cost 155000 USD a year, 5900 tCO2e abated a year, a life of 15 years, acting on the flare, starting in 2029; Lighting and variable speed drives: capital 390000 USD, savings 88000 USD a year, running cost 0 USD a year, 610 tCO2e abated a year, a life of 10 years, acting on the power, starting in 2028; Vapour recovery on the condensate tanks: capital 540000 USD, savings 31000 USD a year, running cost 12000 USD a year, 1400 tCO2e abated a year, a life of 12 years, acting on the vents, no start year agreed yet. The target falls in a straight line from the baseline in 2026 to 35 percent below it in 2034, and each scheduled measure counts in full from its start year. One saving is priced separately: Economiser on the boilers, 9650 GJ a year at 6.8 USD a GJ, a SYNTHETIC factor of 56.1 kg CO2e per GJ, all on LHV, costing 185000 USD over 7 years at a rate of 0.09. Give six numbers, each to two decimals. (1) The cost per tonne of Tune the boilers, USD. (2) The cost per tonne of the waste heat recovery, USD. (3) The net annual cost of the flare gas recovery compressor, USD. (4) The curve''s weighted average cost per tonne over all six measures, USD. (5) The unabated gap in 2034, in tCO2e. (6) The economiser''s cost per tonne of CO2e, USD.',
  jsonb_build_array(
    jsonb_build_object('key','ikorodu_boiler_tuning_cost_per_t_usd', 'label','Cost per tonne of Tune the boilers', 'unit','USD per tCO2e', 'expected',-159.3835, 'tol',0.01),
    jsonb_build_object('key','ikorodu_waste_heat_cost_per_t_usd', 'label','Cost per tonne of the waste heat recovery', 'unit','USD per tCO2e', 'expected',-21.197011, 'tol',0.01),
    jsonb_build_object('key','ikorodu_flare_recovery_net_annual_cost_usd', 'label','Net annual cost of the flare gas recovery compressor', 'unit','USD a year', 'expected',501759.1842, 'tol',0.01),
    jsonb_build_object('key','ikorodu_curve_weighted_average_usd_per_t', 'label','Weighted average cost per tonne of the curve', 'unit','USD per tCO2e', 'expected',12.930882, 'tol',0.01),
    jsonb_build_object('key','ikorodu_path_final_gap_t', 'label','Unabated gap in the end year', 'unit','tCO2e', 'expected',10762.118, 'tol',0.01),
    jsonb_build_object('key','ikorodu_saving_cost_per_t_usd', 'label','Economiser cost per tonne of CO2e', 'unit','USD per tCO2e', 'expected',-53.313854, 'tol',0.01)
  )
)
on conflict (app_slug, tier) do nothing;
